from collections import Counter

def word_freq(text: str) -> dict[str, int]:
    words = (w.strip('.,!?') for w in text.lower().split())
    return dict(Counter(w for w in words if w))

def _walk(items):
    for x in items:
        if isinstance(x, list):
            yield from _walk(x)
        else:
            yield x

def flatten(items):
    return list(_walk(items))

import functools

def retry(times, exceptions=(Exception,)):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last = None
            for _ in range(times):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    last = e
            raise last
        return wrapper
    return decorator

# --- test helpers ---
def _make(fail_times, exc=ValueError):
    state = {"n": 0}
    def flaky():
        state["n"] += 1
        if state["n"] <= fail_times:
            raise exc("boom")
        return "ok"
    return flaky, state

def demo_ok():
    f, _ = _make(2); return retry(3)(f)()
def demo_name():
    f, _ = _make(0); return retry(3)(f).__name__
def demo_gives_up():
    f, _ = _make(5)
    try: retry(3)(f)()
    except ValueError as e: return type(e).__name__
def demo_not_listed():
    f, s = _make(5, KeyError)
    try: retry(3, exceptions=(ValueError,))(f)()
    except KeyError: return f"KeyError after {s['n']} call"

from itertools import islice

def chunked(iterable, size):
    if size < 1:
        raise ValueError("size must be >= 1")
    it = iter(iterable)
    while chunk := list(islice(it, size)):
        yield chunk

def is_balanced(s: str) -> bool:
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in s:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

def two_sum(nums, target):
    seen = {}
    for j, x in enumerate(nums):
        i = seen.get(target - x)
        if i is not None:
            return (i, j)
        seen[x] = j
    return None

def search(sorted_nums, target):
    lo, hi = 0, len(sorted_nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_nums[mid] == target:
            return mid
        if sorted_nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def paginate(items, page, size):
    if page < 1:
        raise ValueError("page must be >= 1")
    if not 1 <= size <= 100:
        raise ValueError("size must be between 1 and 100")
    start = (page - 1) * size
    total = len(items)
    return {"data": items[start:start + size], "page": page, "size": size,
            "total": total, "next": page + 1 if start + size < total else None}

def raises(fn):
    try: fn()
    except Exception as e: return type(e).__name__

