class RateLimiter:
    def __init__(self, limit, window_seconds):
        self.limit, self.window = limit, window_seconds
        self.state = {}                       # client -> (window_no, count)

    def allow(self, client_id, now):
        w = int(now // self.window)
        win, count = self.state.get(client_id, (w, 0))
        if win != w:
            win, count = w, 0
        if count >= self.limit:
            return False
        self.state[client_id] = (win, count + 1)
        return True

def run(calls, limit, window):
    rl = RateLimiter(limit, window)
    return [rl.allow(c, t) for c, t in calls]

def parse_bool(v, default=False):
    if v is None:
        return default
    return v.strip().lower() in {"1", "true", "yes"}

def load_settings(env):
    port = int(env.get("PORT", "8000"))
    if not 1 <= port <= 65535:
        raise ValueError("PORT out of range")
    hosts = [h.strip() for h in env.get("ALLOWED_HOSTS", "").split(",") if h.strip()]
    return {"debug": parse_bool(env.get("DEBUG")), "port": port,
            "allowed_hosts": hosts, "secret_key": env["SECRET_KEY"]}

